#define ENTRY_COUNT (int)(sizeof(ENTRIES) / sizeof(ENTRIES[0]))


static const char *const NAMES[LANG_COUNT] = {"English", "Français", "Deutsch", "Español",
                                              "Italiano", "Português (Portugal)", "中文（简体）",
                                              "한국어", "日本語"};

static int current;

/* English key -> entry, open addressing; built on first use. The table must
 * stay comfortably larger than ENTRY_COUNT: a full table makes both build()
 * and tr() spin forever (that was the language switch freeze). */
#define SLOTS 2048
_Static_assert(SLOTS >= 2048, "SLOTS must hold every entry");
static int16_t slots[SLOTS];
static bool built;

static uint32_t hash(const char *s)
{
    uint32_t h = 2166136261u;
    while (*s)
        h = (h ^ (unsigned char)*s++) * 16777619u;
    return h;
}

static void build(void)
{
    for (int i = 0; i < SLOTS; ++i)
        slots[i] = -1;
    for (int i = 0; i < ENTRY_COUNT; ++i)
    {
        uint32_t h = hash(ENTRIES[i].text[LANG_EN]) % SLOTS;
        int probes = 0;
        while (slots[h] >= 0 && ++probes < SLOTS)
            h = (h + 1) % SLOTS;
        if (slots[h] < 0)
            slots[h] = (int16_t)i;
    }
    built = true;
}

const char *tr(const char *english)
{
    if (current == LANG_EN || !english)
        return english;
    if (!built)
        build();
    for (uint32_t h = hash(english) % SLOTS, probes = 0; slots[h] >= 0 && probes < SLOTS;
         h = (h + 1) % SLOTS, ++probes)
    {
        const Entry *e = &ENTRIES[slots[h]];
        if (strcmp(e->text[LANG_EN], english) == 0)
            return e->text[current] ? e->text[current] : english;
    }
    return english;
}

void i18n_set(int lang)
{
    if (lang < 0 || lang >= LANG_COUNT)
        lang = LANG_EN;
    if (lang == current)
        return;
    current = lang;
    text_language_changed(); /* Japanese needs its glyphs packed */
}

int i18n_get(void)
{
    return current;
}

const char *i18n_name(int lang)
{
    return lang >= 0 && lang < LANG_COUNT ? NAMES[lang] : NAMES[0];
}

const char *i18n_string(int lang, int index)
{
    if (lang < 0 || lang >= LANG_COUNT)
        return NULL;
    if (index < LANG_COUNT) /* the selector shows every language's name */
        return NAMES[index];
    index -= LANG_COUNT;
    return index < ENTRY_COUNT ? ENTRIES[index].text[lang] : NULL;
}
